required = {s.strip().lower() for s in input().split(',') if s.strip()}
allowed = input().strip().upper()
allowed_set = None if allowed == 'ANY' else {c.strip() for c in allowed.split(',')}
n = int(input())

eligible = []
for _ in range(n):
    name, country, latency, price, services = input().split()
    offered = {s.lower() for s in services.split(',')}
    if allowed_set is not None and country.upper() not in allowed_set:
        continue
    if not required <= offered:
        continue
    eligible.append((int(latency), int(price), name))

print('Eligible regions: ' + str(len(eligible)))
if not eligible:
    print('NO SUITABLE REGION')
else:
    latency, price, name = min(eligible)
    print(f'Selected: {name} (latency {latency} ms, price index {price})')
